create policy "Engagement owners can progress materiality workflow" on public.materiality_assessments for update to authenticated using (exists (select 1 from public.engagements e where e.id = engagement_id and e.owner_id = auth.uid()) and status <> 'approved') with check (exists (select 1 from public.engagements e where e.id = engagement_id and e.owner_id = auth.uid()) and status in ('draft', 'senior_review', 'partner_review', 'approved', 'rejected'));